@using sv_a966fc95459b4796aeaed1825367663f.Services

<div class="channel-sidebar">
    <div class="sidebar-header">
        <h3>Channels</h3>
    </div>
    <div class="channel-list">
        @foreach (var channel in Channels)
        {
            <ChannelListItem Channel="channel"
                             IsActive="channel.Id == ActiveChannelId"
                             OnChannelSelected="OnChannelSelected" />
        }
    </div>
</div>

@code {
    [Parameter] public List<Channel> Channels { get; set; } = [];
    [Parameter] public int ActiveChannelId { get; set; }
    [Parameter] public EventCallback<int> OnChannelSelected { get; set; }
}

.channel-sidebar {
    display: flex;
    flex-direction: column;
    background-color: #2c2f33;
    color: #e0e0e0;
    height: 100%;
    overflow: hidden;
}

.sidebar-header {
    padding: 16px;
    border-bottom: 1px solid rgba(255, 255, 255, 0.1);
}

.sidebar-header h3 {
    margin: 0;
    font-size: 1.1rem;
    font-weight: 700;
    color: #fff;
}

.channel-list {
    flex: 1;
    overflow-y: auto;
    padding: 8px 0;
}

@using sv_a966fc95459b4796aeaed1825367663f.Services
@inject IJSRuntime JS

<div class="message-list" @ref="scrollContainer">
    @if (IsLoadingMore)
    {
        <div class="loading-indicator">Loading older messages...</div>
    }
    @foreach (var message in Messages)
    {
        var threadInfo = ThreadSummaries.FirstOrDefault(t => t.RootMessageId == message.Id);
        <ChatMessage Message="message"
                     IsThreadStarter="threadInfo is not null"
                     ReplyCount="threadInfo?.ReplyCount ?? 0"
                     OnReply="OnReply"
                     OnViewThread="OnViewThread"
                     OnReact="OnReact" />
    }
</div>

@code {
    [Parameter] public List<Message> Messages { get; set; } = [];
    [Parameter] public List<ThreadSummary> ThreadSummaries { get; set; } = [];
    [Parameter] public bool IsLoadingMore { get; set; }
    [Parameter] public bool HasMoreMessages { get; set; }
    [Parameter] public EventCallback OnLoadMore { get; set; }
    [Parameter] public EventCallback<int> OnReply { get; set; }
    [Parameter] public EventCallback<int> OnViewThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }

    private ElementReference scrollContainer;
    private DotNetObjectReference<MessageList>? objRef;

    protected override void OnInitialized()
    {
        objRef = DotNetObjectReference.Create(this);
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            await JS.InvokeVoidAsync("chatScrollObserver.init", scrollContainer, objRef);
        }
    }

    [JSInvokable]
    public async Task OnScrolledToTop()
    {
        if (HasMoreMessages && !IsLoadingMore)
        {
            await OnLoadMore.InvokeAsync();
        }
    }

    public void Dispose() => objRef?.Dispose();
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 8px 0;
    display: flex;
    flex-direction: column;
}

.loading-indicator {
    text-align: center;
    padding: 12px;
    color: #999;
    font-size: 0.85rem;
}

@using sv_a966fc95459b4796aeaed1825367663f.Services

<div class="message-area">
