arguments.file_text:
@page "/chat"
@using sv_a966fc95459b4796aeaed1825367663f.Services
@using sv_a966fc95459b4796aeaed1825367663f.Components.Chat
@rendermode InteractiveServer
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-layout">
    <div class="chat-sidebar">
        <ChannelSidebar Channels="channels"
                        ActiveChannelId="activeChannelId"
                        OnChannelSelected="SelectChannel" />
    </div>

    <div class="chat-main @(threadOpen ? "with-thread" : "")">
        <MessageArea Channel="activeChannel"
                     Messages="messages"
                     ThreadSummaries="threadSummaries"
                     IsLoadingMore="isLoadingMore"
                     HasMoreMessages="hasMoreMessages"
                     OnLoadMore="LoadMoreMessages"
                     OnReply="OpenThread"
                     OnViewThread="OpenThread"
                     OnReact="HandleReaction"
                     OnSendMessage="SendMessage" />
    </div>

    @if (threadOpen)
    {
        <div class="chat-thread">
            <ThreadPanel RootMessage="threadRootMessage"
                         ThreadMessages="threadMessages"
                         OnClose="CloseThread"
                         OnSendReply="SendThreadReply"
                         OnReact="HandleReaction" />
        </div>
    }
</div>

@code {
    private const int PageSize = 30;

    private List<Channel> channels = [];
    private List<Message> messages = [];
    private List<ThreadSummary> threadSummaries = [];

    private Channel? activeChannel;
    private int activeChannelId;
    private int loadedCount;
    private bool isLoadingMore;
    private bool hasMoreMessages = true;

    // Thread state
    private bool threadOpen;
    private Message? threadRootMessage;
    private List<Message> threadMessages = [];

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
        if (channels.Count > 0)
        {
            await SelectChannel(channels[0].Id);
        }
    }

    private async Task SelectChannel(int channelId)
    {
        activeChannelId = channelId;
        activeChannel = channels.FirstOrDefault(c => c.Id == channelId);
        messages = [];
        loadedCount = 0;
        hasMoreMessages = true;
        threadOpen = false;

        await LoadMessages();
        await ChatService.MarkChannelReadAsync(channelId);

        // Refresh channels to update unread counts
        channels = await ChatService.GetChannelsAsync();
    }

    private async Task LoadMessages()
    {
        var batch = await ChatService.GetMessagesAsync(activeChannelId, loadedCount, PageSize);
        messages.InsertRange(0, batch);
        loadedCount += batch.Count;
        hasMoreMessages = batch.Count == PageSize;

        await RefreshThreadSummaries();
    }

    private async Task LoadMoreMessages()
    {
        if (isLoadingMore || !hasMoreMessages) return;
        isLoadingMore = true;
        StateHasChanged();

        await LoadMessages();

        isLoadingMore = false;
    }

    private async Task RefreshThreadSummaries()
    {
        // Build thread summaries from messages that have replies
        var rootIds = messages
            .Where(m => m.ReplyToId is null)
            .Select(m => m.Id)
            .ToHashSet();

        var summaries = new List<ThreadSummary>();
        foreach (var rootId in rootIds)
        {
            var replies = messages.Where(m => m.ReplyToId == rootId).ToList();
            if (replies.Count > 0)
            {
                summaries.Add(new ThreadSummary(rootId, replies.Count, replies.Max(r => r.SentAt)));
            }
            else
            {
                // Check if there are thread replies via the service
                try
                {
                    var thread = await ChatService.GetThreadAsync(rootId);
                    if (thread.Count > 0)
                    {
                        summaries.Add(new ThreadSummary(rootId, thread.Count, thread.Max(r => r.SentAt)));
                    }
                }
                catch
                {
                    // Thread may not exist; skip
                }
            }
        }
        threadSummaries = summaries;
    }

    private async Task SendMessage(string content)
    {
        var message = await ChatService.SendMessageAsync(activeChannelId, content, null);
        messages.Add(message);
    }

    private async Task OpenThread(int messageId)
    {
        threadRootMessage = messages.FirstOrDefault(m => m.Id == messageId);
        if (threadRootMessage is null) return;

        threadMessages = await ChatService.GetThreadAsync(messageId);
        threadOpen = true;
    }

    private void CloseThread()
    {
        threadOpen = false;
        threadRootMessage = null;
        threadMessages = [];
    }

    private async Task SendThreadReply(string content)
    {
        if (threadRootMessage is null) return;

        var reply = await ChatService.SendMessageAsync(activeChannelId, content, threadRootMessage.Id);
        threadMessages.Add(reply);

        // Update thread summary
        await RefreshThreadSummaries();
    }

    private async Task HandleReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);

        // Refresh messages to pick up the new reaction
        var updatedMessages = await ChatService.GetMessagesAsync(activeChannelId, 0, loadedCount);
        messages = updatedMessages;

        // Refresh thread if open
        if (threadOpen && threadRootMessage is not null)
        {
            threadMessages = await ChatService.GetThreadAsync(threadRootMessage.Id);
            threadRootMessage = messages.FirstOrDefault(m => m.Id == threadRootMessage.Id)
                ?? threadRootMessage;
        }
    }
}

.chat-layout {
    display: flex;
    height: calc(100vh - 3.5rem);
    overflow: hidden;
    border: 1px solid #e0e0e0;
    border-radius: 4px;
    margin: -1.5rem;
}

.chat-sidebar {
    width: 20%;
    min-width: 200px;
    flex-shrink: 0;
}

.chat-main {
    flex: 1;
    min-width: 0;
}

.chat-main.with-thread {
    flex: 0 0 55%;
}

.chat-thread {
    width: 25%;
    min-width: 280px;
    flex-shrink: 0;
}

window.chatScrollObserver = {
    init: function (scrollContainer, dotNetRef) {
        if (!scrollContainer) return;
        scrollContainer.addEventListener('scroll', function () {
            if (scrollContainer.scrollTop === 0) {
                dotNetRef.invokeMethodAsync('OnScrolledToTop');
            }
        });
    }
};

